export function encodeSegment(value: string): string {
  // A component must never contribute a structural path separator.
  return encodeURI(value);
}
import {encodeSegment} from "./path_segment_roundtrip.ts";

export function buildPath(parts: string[]): string {
  return "/" + parts.filter(Boolean).map(encodeSegment).join("/");
}
